package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonIdentityInfo;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.annotation.SimpleObjectIdResolver;
import com.fasterxml.jackson.databind.PropertyName;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;

public class ObjectIdInfo_withAlwaysAsId_TriageGen2Test {

    private PropertyName mockPropertyName;
    private Class<?> mockScope;
    private Class<? extends com.fasterxml.jackson.databind.annotation.ObjectIdGenerator> mockGenerator;
    private Class<? extends com.fasterxml.jackson.databind.annotation.ObjectIdResolver> mockResolver;

    @Before
    public void setUp() {
        mockPropertyName = mock(PropertyName.class);
        mockScope = Object.class;
        mockGenerator = com.fasterxml.jackson.databind.annotation.ObjectIdGenerators.UUIDGenerator.class;
        mockResolver = com.fasterxml.jackson.databind.annotation.ObjectIdResolver.class;
    }

    @Test
    public void testWithAlwaysAsId_ReturnsThisWhenStateIsSame() {
        // Arrange: Create initial object with alwaysAsId = true
        ObjectIdInfo originalInfo = new ObjectIdInfo(mockPropertyName, mockScope, mockGenerator, true, mockResolver);

        // Act: Call with same state (true)
        ObjectIdInfo result = originalInfo.withAlwaysAsId(true);

        // Assert: Should return the exact same instance (identity)
        Assert.assertSame("Should return the same instance when state is unchanged", originalInfo, result);
    }

    @Test
    public void testWithAlwaysAsId_ReturnsThisWhenStateIsSameFalse() {
        // Arrange: Create initial object with alwaysAsId = false
        ObjectIdInfo originalInfo = new ObjectIdInfo(mockPropertyName, mockScope, mockGenerator, false, mockResolver);

        // Act: Call with same state (false)
        ObjectIdInfo result = originalInfo.withAlwaysAsId(false);

        // Assert: Should return the exact same instance (identity)
        Assert.assertSame("Should return the same instance when state is unchanged", originalInfo, result);
    }

    @Test
    public void testWithAlwaysAsId_ReturnsNewInstanceWhenStateChangesToTrue() {
        // Arrange: Create initial object with alwaysAsId = false
        ObjectIdInfo originalInfo = new ObjectIdInfo(mockPropertyName, mockScope, mockGenerator, false, mockResolver);

        // Act: Call with different state (true)
        ObjectIdInfo result = originalInfo.withAlwaysAsId(true);

        // Assert: Should be a new instance and have the new state
        Assert.assertNotSame("Should return a new instance when state changes", originalInfo, result);
        Assert.assertTrue("New instance should have alwaysAsId set to true", result.getAlwaysAsId());
        Assert.assertEquals("Properties should be preserved in new instance", originalInfo.getPropertyName(), result.getPropertyName());
        Assert.assertEquals("Scope should be preserved", originalInfo.getScope(), result.getScope());
        Assert.assertEquals("Generator should be preserved", originalInfo.getGeneratorType(), result.getGeneratorType());
        Assert.assertEquals("Resolver should be preserved", originalInfo.getResolverType(), result.getResolverType());
    }

    @Test
    public void testWithAlwaysAsId_ReturnsNewInstanceWhenStateChangesToFalse() {
        // Arrange: Create initial object with alwaysAsId = true
        ObjectIdInfo originalInfo = new ObjectIdInfo(mockPropertyName, mockScope, mockGenerator, true, mockResolver);

        // Act: Call with different state (false)
        ObjectIdInfo result = originalInfo.withAlwaysAsId(false);

        // Assert: Should be a new instance and have the new state
        Assert.assertNotSame("Should return a new instance when state changes", originalInfo, result);
        Assert.assertFalse("New instance should have alwaysAsId set to false", result.getAlwaysAsId());
        Assert.assertEquals("Properties should be preserved in new instance", originalInfo.getPropertyName(), result.getPropertyName());
        Assert.assertEquals("Scope should be preserved", originalInfo.getScope(), result.getScope());
        Assert.assertEquals("Generator should be preserved", originalInfo.getGeneratorType(), result.getGeneratorType());
        Assert.assertEquals("Resolver should be preserved", originalInfo.getResolverType(), result.getResolverType());
    }
}
